package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object DebtCards {
    private val T = Track.DEBT
    val cards: List<Card> = listOf(
        // ---------- Level 1: Rookie ----------
        concept("db-principal", T, 1, "In a loan, what is the \"principal\" and what is the \"interest\"?",
            "Principal is the amount you borrowed. Interest (plus fees) is the price you pay for using someone else's money. Every repayment covers some of each."),
        quiz("db-flat-intro", T, 1, "A shylock or microlender quotes \"10% flat\". Flat means interest is charged on…",
            listOf("The full amount borrowed, for the whole term", "Only what you still owe each month", "Only the payments you miss"), 0,
            "Flat interest is always worked out on the original amount, even after you've repaid most of it. That makes it far dearer than it sounds."),
        quiz("db-mshwari-fee", T, 1, "M-Shwari charges a 7.5% fee on a 30-day loan, plus 20% excise duty on that fee. A Ksh 1,000 loan costs about…",
            listOf("Ksh 75", "Ksh 90", "Ksh 9"), 1,
            "Fee Ksh 75 + excise Ksh 15 (20% of 75) = Ksh 90, or 9% for one month. The excise is taken upfront, so about Ksh 985 lands (check current terms).",
            source = "Safaricom / NCBA, 2026", timeSensitive = true),
        concept("db-minimum", T, 1, "What happens if you only ever pay the minimum amount due?",
            "Most of each payment goes to interest and the debt drags on for years. Minimums are set so you stay a customer for a long time. Paying even a little above the minimum cuts both the time and the total interest."),
        concept("db-spiral", T, 1, "What is a debt spiral?",
            "Borrowing from one lender to repay another. Each new loan adds fees, so the total grows while nothing is actually paid off. The exit is to stop new borrowing and attack one debt at a time.",
            tryThis = "List every loan app on your phone and what you owe on each.", signals = setOf(Signal.HAS_DEBT)),

        // ---------- Level 2: Hustler ----------
        quiz("db-monthly-to-year", T, 2, "A loan costs 5% a month. As a simple yearly rate, that's about…",
            listOf("5%", "12%", "60%"), 2,
            "5% × 12 months = 60% a year, before any compounding. Always turn monthly or daily prices into a yearly rate before comparing.",
            source = "Basic maths"),
        quiz("db-mshwari-apr", T, 2, "If you take a 9%-for-30-days mobile loan every month, the simple yearly rate is roughly…",
            listOf("About 9%", "About 30%", "About 110%"), 2,
            "9% × (365 ÷ 30) ≈ 110% a year. Fine for a true one-off emergency; a very expensive habit.",
            source = "Basic maths", signals = setOf(Signal.HAS_DEBT)),
        quiz("db-flat-vs-reducing", T, 2, "Ksh 100,000 over 12 months: 12% flat costs Ksh 12,000 interest. At 12% reducing balance it costs about…",
            listOf("Ksh 12,000", "Ksh 6,600", "Ksh 1,200"), 1,
            "On a reducing balance you only pay interest on what's still owed, so the 12 equal payments (about Ksh 8,885) total about Ksh 106,600: roughly half the flat-rate interest.",
            source = "Loan amortisation maths"),
        quiz("db-fees-upfront", T, 2, "A Ksh 200,000 loan has a 2% processing fee and 1% insurance taken upfront. What reaches you?",
            listOf("Ksh 200,000", "Ksh 194,000", "Ksh 197,000"), 1,
            "Ksh 6,000 is deducted, so you get Ksh 194,000 but repay interest on the full Ksh 200,000. Upfront fees quietly raise the true rate.",
            tryThis = "Ask the lender for the APR and the total amount payable, in writing."),
        quiz("db-min-trap", T, 2, "You owe Ksh 50,000 at 3% a month and pay Ksh 1,500 a month. After a year you owe…",
            listOf("About Ksh 32,000", "About Ksh 50,000", "Nothing"), 1,
            "3% of 50,000 is exactly Ksh 1,500, so every payment is pure interest. You'd pay Ksh 18,000 a year and the debt never shrinks.",
            source = "Basic maths", signals = setOf(Signal.HAS_DEBT)),
        quiz("db-helb-rate", T, 2, "Interest on an undergraduate HELB loan is…",
            listOf("4% a year, after a one-year grace period", "14% a year from day one", "Zero; it's a grant"), 0,
            "The HELB Act sets 4% a year, with repayment starting a year after you finish studies, whether or not you're employed. Missed payments add monthly penalties and CRB listing (check current terms).",
            source = "HELB Act; K24, 2026", timeSensitive = true),
        quiz("db-crb-1000", T, 2, "Under the CRB Regulations 2020, lenders can't report you as a defaulter to a CRB if you owe less than…",
            listOf("Ksh 100", "Ksh 1,000", "Ksh 10,000"), 1,
            "The 2020 rules set a Ksh 1,000 minimum for negative listing, and people listed only for smaller amounts were delisted. Small debts still cost you in fees and access.",
            source = "CBK, CRB Regulations 2020", timeSensitive = true),
        concept("db-clearance", T, 2, "What is a CRB clearance certificate, and what does your first one cost?",
            "It's a bureau's statement that you have no outstanding default on record, often asked for by employers or lenders. The CRB Regulations 2020 made your first one free; later ones carry a fee.",
            source = "CBK, CRB Regulations 2020", tryThis = "Check your status with a CRB by SMS or app.", timeSensitive = true),
        quiz("db-two-thirds", T, 2, "Kenya's Employment Act limits total deductions from your wages (including loan check-offs) to…",
            listOf("One-third of wages", "Two-thirds of wages", "There's no limit"), 1,
            "Section 19(3) caps deductions at two-thirds, so you keep at least a third. New levies have pushed many payslips against this limit, so check yours.",
            source = "Employment Act 2007, s.19(3)"),
        concept("db-good-test", T, 2, "You borrow at 18% a year to stock your duka. When is that \"good\" debt?",
            "Only when what it buys earns well above 18% after costs, with room to spare for slow months. Good debt pays for itself; bad debt doesn't. Same loan, different business, different answer."),
        you("db-you-savings", T, 2, "You owe {debts} and have {savings} saved. Why not wipe out the debt with your savings?",
            "Keep an emergency buffer first (your target is {emergency_target}), or the next shock sends you back to Fuliza. Money beyond that is usually best used on the most expensive debt.",
            tryThis = "Compare each debt's yearly cost with what your savings earn.", action = Action.ACCOUNTS, signals = setOf(Signal.HAS_DEBT)),

        // ---------- Level 3: Pro ----------
        quiz("db-flat-to-apr", T, 3, "A 1-year loan at 12% flat, repaid monthly, is roughly equal to what reducing-balance rate?",
            listOf("About 12%", "About 21.5%", "About 6%"), 1,
            "Solving for the rate on 12 payments of Ksh 9,333 per 100,000 gives about 1.79% a month, roughly 21.5% a year. Rule of thumb: a flat rate is close to double its true rate.",
            source = "Loan amortisation maths"),
        quiz("db-avalanche-math", T, 3, "You have Ksh 10,000 spare. Debt A costs 9% a month, Debt B 1% a month. Paying A instead of B saves you how much a month?",
            listOf("Ksh 100", "Ksh 800", "Ksh 900"), 1,
            "On A you avoid Ksh 900 of interest; on B only Ksh 100. Difference: Ksh 800 a month, nearly Ksh 10,000 a year. That's the avalanche method in numbers.",
            source = "Basic maths", signals = setOf(Signal.HAS_DEBT)),
        quiz("db-dti", T, 3, "Your take-home pay is Ksh 60,000 and loan repayments are Ksh 24,000 a month. Your debt-to-income ratio is…",
            listOf("24%", "40%", "60%"), 1,
            "24,000 ÷ 60,000 = 40%. Lenders use this ratio to judge risk; a common rule of thumb is to keep repayments well under a third of take-home pay.",
            source = "Basic maths"),
        concept("db-crb-names", T, 3, "Which credit reference bureaus operate in Kenya?",
            "Three are licensed by CBK: Metropol, TransUnion and Creditinfo. Banks, microfinance banks, SACCOs and licensed digital lenders share both positive and negative data with them.",
            source = "CBK, 2026"),
        quiz("db-crb-notice", T, 3, "A bank loan is in arrears. Before it lists you with a CRB, the lender must…",
            listOf("Do nothing; listing is automatic", "Give you notice and a 30-day window to regularise", "Get a court order"), 1,
            "CBK's procedure: after arrears, the lender sends notice of intent to list; if the loan isn't regularised within 30 days, it's listed. That window is your chance to negotiate.",
            source = "CBK, 2021"),
        concept("db-crb-positive", T, 3, "Is a CRB a \"blacklist\"?",
            "No. CRBs hold your whole repayment history, good and bad. A long record of on-time repayment builds a score that can earn you bigger, cheaper loans. Errors can be disputed with the bureau.",
            source = "CBK, CRB Regulations 2020", tryThis = "Request your credit report and check every loan on it is really yours."),
        quiz("db-guarantor", T, 3, "You guaranteed a friend's SACCO loan and they stop paying. Typically…",
            listOf("Nothing happens to you", "The SACCO can recover from your deposits and limit your own borrowing", "The loan is written off"), 1,
            "A guarantee is a real debt in waiting. SACCO by-laws usually let them attach the guarantor's deposits for the unpaid share. Only guarantee what you could afford to lose.",
            source = "SACCO by-laws (typical)"),
        concept("db-sacco-multiplier", T, 3, "Your SACCO lends 3× your deposits. What's the hidden cost of that cheap loan?",
            "Your deposits are locked as security while you repay, often earning less than the loan costs. To borrow Ksh 300,000 you tie up Ksh 100,000, so compare the whole package, not just the headline rate."),
        quiz("db-logbook", T, 3, "With a logbook loan, before the lender can repossess your car after a default, the law requires…",
            listOf("Nothing; they can take it at once", "A written default notice giving you time to fix it", "Your employer's permission"), 1,
            "Under the Movable Property Security Rights Act 2017 (s.67), the lender must serve written notice of default first. Courts have faulted repossessions done without it.",
            source = "MPSRA 2017; Kenya High Court, 2025"),
        quiz("db-asset-financing", T, 3, "A phone costs Ksh 15,000 cash, or Ksh 1,000 deposit + Ksh 50 a day for a year. How much more is the plan?",
            listOf("About 5% more", "About 28% more", "About 100% more"), 1,
            "1,000 + 50 × 365 = Ksh 19,250, which is Ksh 4,250 or about 28% above cash. It may still be worth it if the phone earns you money; just see the full price.",
            source = "Basic maths"),
        concept("db-chama-loan", T, 3, "Your chama lends at \"10% a month\". Is that cheap because it's among friends?",
            "No: 10% a month is 120% a year, even before compounding. The interest does return to members as profit, so it's good for savers but hard on borrowers. Price it like any other loan."),
        quiz("db-mshwari-rollover", T, 3, "An unpaid M-Shwari loan rolls over after 30 days. What happens to the cost?",
            listOf("Nothing; the fee is one-off", "Another 7.5% fee is charged on the unpaid balance", "Interest stops"), 1,
            "A rollover adds a fresh 7.5% fee on what's left, and repeated defaults can get you listed. Repay or negotiate before day 30 (check current terms).",
            source = "Safaricom / NCBA, 2026", timeSensitive = true, signals = setOf(Signal.HAS_DEBT)),
        concept("db-cost-of-credit", T, 3, "Where can you compare the full cost of bank loans in Kenya?",
            "The Kenya Bankers Association's cost of credit site (costofcredit.co.ke) shows interest, fees and third-party costs for each bank's loans, so you can compare the total amount payable.",
            source = "KBA / CBK, 2017", tryThis = "Price a Ksh 500,000 loan on costofcredit.co.ke across three banks."),

        // ---------- Level 4: Shark ----------
        concept("db-tcc", T, 4, "What goes into a loan's Total Cost of Credit?",
            "Interest, fees, insurance, taxes and third-party costs. Since 2014 Kenyan banks must disclose an APR built from all these costs. Legal, valuation and insurance fees can add several points to a mortgage or asset loan.",
            source = "KBA / CBK, 2014"),
        quiz("db-compound", T, 4, "A loan costing 9% a month, left to compound for a year, costs about what effective annual rate?",
            listOf("108%", "181%", "300%"), 1,
            "1.09¹² − 1 ≈ 1.81, so about 181%. The simple rate (108%) understates it because each month's charge also gets charged.",
            source = "Compound interest maths"),
        quiz("db-consolidate", T, 4, "You move Ksh 60,000 of mobile loans (~9% a month) to a bank loan at 18% a year. Monthly interest falls from ~Ksh 5,400 to about…",
            listOf("Ksh 4,500", "Ksh 2,700", "Ksh 900"), 2,
            "18% ÷ 12 = 1.5% a month, or Ksh 900. Consolidation only works if you also stop taking new mobile loans; otherwise you end up with both.",
            source = "Basic maths", signals = setOf(Signal.HAS_DEBT)),
        quiz("db-refi-breakeven", T, 4, "Refinancing costs Ksh 30,000 in fees and cuts your repayment by Ksh 2,500 a month. Break-even is after…",
            listOf("12 months", "6 months", "30 months"), 0,
            "30,000 ÷ 2,500 = 12 months. If you'd pay off or move again sooner, refinancing loses money. Also check it doesn't simply stretch the term.",
            source = "Basic maths"),
        quiz("db-variable-rate", T, 4, "Ksh 1M over 5 years at 14% costs about Ksh 23,300 a month. If a variable rate rises to 16%, the payment becomes about…",
            listOf("Ksh 23,500", "Ksh 24,300", "Ksh 26,700"), 1,
            "About Ksh 24,300, over Ksh 1,000 more each month. Most Kenyan bank loans are variable and move with the CBR, so stress-test your budget at +2 to 3 points.",
            source = "Loan amortisation maths"),
        concept("db-dscr", T, 4, "What is a debt service coverage ratio (DSCR), and why do business lenders care?",
            "DSCR = cash the business generates ÷ loan repayments due. Above 1 means it can pay; many banks look for a cushion of about 1.2–1.5×. Know yours before you ask for business credit.",
            source = "Standard credit analysis"),
        quiz("db-ratecap", T, 4, "Kenya's 2016 interest rate cap limited bank lending rates to…",
            listOf("4 points above the CBK's central bank rate", "Half of the CBR", "A flat 10%"), 0,
            "The Banking (Amendment) Act 2016 capped loans at CBR + 4 points and set a deposit-rate floor of 70% of CBR. It was repealed by the Finance Act 2019 in November 2019.",
            source = "Banking (Amendment) Act 2016; KBA"),
        concept("db-ratecap-effect", T, 4, "What happened to bank lending under the 2016–2019 rate cap?",
            "Banks cut risky lending, especially to SMEs, and bought more government debt. With prices capped, they rationed credit to the safest borrowers. Analysts estimate SMEs' share of bank loans fell from about 25% to 15%; the President cited reduced private credit when repealing it.",
            source = "African Business, 2020; CNBC, 2019"),
        concept("db-dcp-regs", T, 4, "What must a digital lender do under the CBK Digital Credit Providers Regulations 2022?",
            "DCPs need CBK licensing (about 280 licensed by 2026), full cost disclosure, data protection and fair debt collection. Check CBK's list before borrowing.",
            source = "CBK, 2026", timeSensitive = true, tryThis = "Search CBK's list of licensed digital credit providers before using a loan app."),
        concept("db-ndtcp", T, 4, "What changed for lenders after the Business Laws (Amendment) Act 2024?",
            "CBK's remit widened from digital lenders to all non-deposit-taking credit providers, covering more of the lenders outside banks. New regulations are set to replace the 2022 DCP rules.",
            source = "CBK Regulatory Impact Assessment, 2026", timeSensitive = true),
        quiz("db-in-duplum", T, 4, "Kenya's in duplum rule (Banking Act s.44A) says that on a bad loan, a bank can recover at most…",
            listOf("Unlimited interest and penalties", "The principal, plus interest up to the principal, plus recovery costs", "The principal only"), 1,
            "Once a loan is non-performing, interest and charges stop growing when they equal the principal owed at default. A Ksh 100,000 default can't legally balloon past about Ksh 200,000 plus costs.",
            source = "Banking Act, s.44A (2006)"),
        concept("db-negotiate", T, 4, "You can't make this month's repayment. What's the strongest way to negotiate?",
            "Contact the lender before you default, show your real budget, and propose something specific: a lower instalment, longer term or penalty waiver. Get any deal in writing. Lenders prefer a plan to a write-off.",
            tryThis = "Write down the instalment you can truly afford before you call.", signals = setOf(Signal.HAS_DEBT)),

        // ---------- Level 5: Legend ----------
        quiz("db-insolvency-discharge", T, 5, "Under Kenya's Insolvency Act 2015, a person declared bankrupt is normally discharged…",
            listOf("Never", "Automatically after three years, unless someone objects", "After 20 years"), 1,
            "Section 254 gives automatic discharge after three years (earlier on application), unless the trustee or a creditor objects. The 2015 Act replaced the old Bankruptcy Act.",
            source = "Insolvency Act 2015, s.254"),
        concept("db-insolvency-options", T, 5, "What options short of bankruptcy does the Insolvency Act 2015 give individuals?",
            "Individuals can agree a voluntary arrangement with creditors, get a summary instalment order, or, with no realisable assets, use the no-asset procedure (discharged after 12 months, usable once).",
            source = "Insolvency Act 2015; Oraro & Co, 2022"),
        quiz("db-mental-health", T, 5, "A 2013 meta-analysis of 65 studies (Richardson et al.) found people in debt had roughly what odds of a mental disorder?",
            listOf("No difference", "About 3 times higher", "About 30 times higher"), 1,
            "Pooled odds ratio 3.24, and higher still for depression and suicide. Most studies were cross-sectional, so cause and effect run both ways. Debt worry is common; talking about it helps.",
            source = "Richardson, Elliott & Roberts, 2013"),
        quiz("db-mshwari-study", T, 5, "Bharadwaj, Jack & Suri studied M-Shwari loans. Eligible households were…",
            listOf("Much richer a year later", "6.3 points less likely to cut spending after a shock", "More likely to go bankrupt"), 1,
            "Digital credit helped households absorb shocks, but didn't raise savings or productive assets. Useful insurance, not a path to wealth.",
            source = "Bharadwaj, Jack & Suri, 2021 (J. Dev. Econ.)"),
        quiz("db-small-defaults", T, 5, "CBK data showed what share of digital loans under Ksh 1,000 went unpaid?",
            listOf("About 8%", "About 40%", "About 83%"), 2,
            "Around 83%, falling as loan size rises. Tiny loans are easy to take and easy to forget, which is why lenders price them so high.",
            source = "CBK via Business Daily, 2025", timeSensitive = true),
        quiz("db-finaccess", T, 5, "The 2024 FinAccess survey found the share of Kenyan borrowers who defaulted had risen to about…",
            listOf("5%", "16.6%", "50%"), 1,
            "Up from 10.7% in 2021, linked to the spread of mobile and digital loans, especially among young and first-time borrowers.",
            source = "FinAccess Household Survey, 2024", timeSensitive = true),
        quiz("db-fuliza-scale", T, 5, "In the six months to September 2025, the average Fuliza draw was about…",
            listOf("Ksh 255", "Ksh 2,550", "Ksh 25,500"), 0,
            "About Ksh 255, with Ksh 629 billion lent to 9.1 million users. Tiny, frequent overdrafts add up: daily fees on small sums give some of the highest yearly rates around.",
            source = "Safaricom HY results, 2025", timeSensitive = true, signals = setOf(Signal.FULIZA_RECENT)),
        concept("db-snowball-study", T, 5, "Why can the snowball method work even though avalanche is cheaper?",
            "Gal & McShane (2012) found that people who closed out whole small debts were more likely to clear all their debt. Small wins keep you going. Pick the method you'll actually stick with.",
            source = "Gal & McShane, 2012 (J. Marketing Research)"),
        concept("db-scarcity", T, 5, "Why do smart people take very expensive loans when money is tight?",
            "Mullainathan & Shafir's \"Scarcity\" (2013): scarcity narrows focus to today's gap (\"tunnelling\"), so future costs fade from view. The fix is to decide rules in calm times, like a buffer before any loan.",
            source = "Mullainathan & Shafir, 2013"),
        quiz("db-murabaha", T, 5, "In an Islamic murabaha, instead of charging interest, the bank…",
            listOf("Lends for free", "Buys the asset and sells it to you at an agreed mark-up, paid in instalments", "Takes a share of your salary"), 1,
            "It's a cost-plus sale: the price and profit are fixed upfront, so the amount owed doesn't grow with time. Kenyan Islamic banks and Islamic windows use it for cars, homes and stock.",
            source = "AAOIFI Shari'ah Standard No. 8"),
        concept("db-murabaha-cost", T, 5, "Is murabaha automatically cheaper than an ordinary loan?",
            "No. The mark-up is priced against market rates, so the total cost can be similar. Compare the total amount payable and any late-payment charges, just as you would with any other loan.",
            source = "AAOIFI; standard practice"),
        concept("db-in-duplum-edge", T, 5, "Does the in duplum rule protect you from every lender?",
            "Unclear. In one case the High Court held s.44A doesn't bind non-bank lenders; in a HELB case a court said it applied to all lenders. A 2025 petition asked Parliament to write it into consumer law.",
            source = "Strathmore Law Review; Afriwise; AllAfrica, 2025"),
        concept("db-case-stack", T, 5, "Case: Achieng has Fuliza, two app loans and a SACCO loan, and borrows from one to pay another. What's step one?",
            "Stop new borrowing, list every debt with its yearly cost, keep a small buffer, then pay minimums on all and throw everything extra at the costliest. Call lenders early to restructure the rest.",
            tryThis = "Rank your debts by yearly cost in a list.", action = Action.ACCOUNTS, signals = setOf(Signal.HAS_DEBT)),
    )
}
